public class Tester {
    public static void main(String[] args) {
        int tamano = 4;
        for (int i = 0; i < tamano; i++) {
            for (int j = i; j > 0; j--) {
                System.out.print(" " );
            }
            for (int j = tamano - i; j > 0; j--) {
                System.out.print("*");
            }
            System.out.println();
        }
    }
}
